import {vacancyBandSource as source} from './planning-vacancy-band-data.js';
export const vacancyBandDefinitions={vacancyBand:{mode:'statistics',sourceChoice:'source view',title:'Compare historical rental vacancy rates within rent quartiles',fields:[
  ['vacancyYear','Source year to display',2025,2015,2025,1],
  ['vacancyReference','Reference year for the rate change',2024,2015,2025,1],
  ['vacancyBand','Rent quartile to trace: 1 lowest, 4 highest',1,1,4,1]
]}};
export function vacancyBandComparison(input){
  const current=source.years.indexOf(input.vacancyYear),reference=source.years.indexOf(input.vacancyReference),band=source.bands[input.vacancyBand-1];
  return {current,reference,band,selected:band.values[current]/100,change:(band.values[current]-band.values[reference])/100,gap:(source.bands[3].values[current]-source.bands[0].values[current])/100};
}
export function vacancyBandResult(kind,input){
  if(kind!=='vacancyBand')throw Error('Unknown vacancy-band topic.');
  const p=vacancyBandComparison(input),common={source:source.url,sourceLabel:'CMHC · 2025 Rental Market Report, national Figure 2 · released 11 December 2025'};
  return {metrics:[['Selected '+p.band.label.toLowerCase()+' · '+input.vacancyYear+' vacancy rate',p.selected,'percent'],['Selected rent band: '+input.vacancyYear+' minus '+input.vacancyReference,p.change,'pp'],['Highest-rent minus lowest-rent quartile vacancy rate · '+input.vacancyYear,p.gap,'pp']],note:'Historical public CMHC Figure 2 snapshot with 44 rounded vacancy-rate estimates across four rent quartiles and eleven years, 2015–2025, retrieved 25 October 2026. Q1–Q4 refer to rent quartiles, not calendar quarters, income groups or four observed cash budgets. The figure concerns Canada’s purpose-built rental apartments; it is not the condominium-rental series or a database of current listings. Controls select and subtract source observations only. No rent cutoffs, band-specific unit counts, standard errors or quality codes are supplied by this HTML figure, and none is invented. Membership and rental stock can change across years; the line does not follow the same units. These rates do not estimate a household’s application success, search duration, affordable choices or future rent.',charts:[
    {id:'vacancy-band-year-comparison',type:'groupbar',title:'Compare the vacancy rate inside each rent band in two historical snapshots',unit:'percent',unitLabel:'Published vacancy rate within the source rent quartile · not a share of applicants',seriesNames:[String(input.vacancyReference)+' source rate',String(input.vacancyYear)+' source rate'],rows:source.bands.map(band=>({label:band.label,values:[band.values[p.reference]/100,band.values[p.current]/100]})),...common,note:'Each bar uses the corresponding rent-quartile denominator. It does not show what percentage of all vacant units belongs to that band. The source’s rent quartiles are retained without inventing dollar boundaries or treating the lowest-rent group as a particular household’s affordability category. Rates were published to one decimal place.'},
    {id:'vacancy-band-rate-changes',type:'signedbar',title:'Calculate the change in percentage points before describing its size',unit:'pp',unitLabel:'Percentage-point change · displayed year minus reference year',rows:source.bands.map(band=>({label:band.label,value:(band.values[p.current]-band.values[p.reference])/100})),...common,evidence:'Derived from official statistics',note:'A rate moving from 0.7% to 1.4% rises 0.7 percentage points, or 100% relative to its original rate. The chart displays the percentage-point difference. Choosing the same year gives zero, while reversing the two years reverses the sign. The arithmetic does not establish statistical significance or identify a cause.'},
    {id:'vacancy-band-history',type:'line',title:p.band.label+': an eleven-year rate history with changing rental stock',unit:'percent',unitLabel:'Published vacancy rate within the selected source rent quartile',xLabel:'Survey year',xTicks:[0,5,10].map(i=>({value:i,label:String(source.years[i])})),series:[{name:p.band.label,rows:source.years.map((year,i)=>({x:i,label:String(year),value:p.band.values[i]/100}))}],...common,note:'All eleven values come from one published Figure 2 vintage, rather than combining independently downloaded annual releases. Rent-band membership and the stock of surveyed units can change. The line summarizes historical annual snapshots, not a fixed-property panel, a monthly listing count, a projected trend or the time a renter must wait. Year selectors leave this full history unchanged.'},
    {id:'vacancy-band-snapshot-matrix',type:'heatmap',title:'The ordering of rent-band vacancy rates changes across the historical snapshots',unit:'percent',unitLabel:'Published vacancy rate · selected historical years and rent quartiles',columns:['2015','2019','2021','2023','2025'],rows:source.bands.map(band=>({label:band.short,values:[2015,2019,2021,2023,2025].map(year=>band.values[source.years.indexOf(year)]/100)})),...common,note:'Rows retain rent-rank labels from lowest to highest; columns are survey years. Darker shading means a larger rate within a band, not a larger number of available units or better affordability. This fixed context matrix does not change with the selectors. No unweighted average of its four percentages is presented as the overall national vacancy rate.'}
  ]};
}
